return {["store:0"]={["no"]="手记 01",["title"]="反方向转 · 世界倒带",["sub"]="按住 K / Shift，世界沿原路倒退，猪不会退",["svg"]="<svg viewBox=\"0 0 520 190\" class=\"mc-svg\" aria-hidden=\"true\">  <defs>    <marker id=\"mc-arr\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 1 1 L 9 5 L 1 9 z\" fill=\"#2b211d\"/></marker>    <marker id=\"mc-arr-b\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 1 1 L 9 5 L 1 9 z\" fill=\"#0140c4\"/></marker>  </defs>  <g transform=\"translate(24,20)\">    <rect x=\"0\" y=\"0\" width=\"168\" height=\"148\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"12\" y=\"22\" font-size=\"13\" fill=\"#7a6e5d\">① 货架倒下堵住去路</text>    <circle cx=\"42\" cy=\"96\" r=\"18\" fill=\"#f7c8c0\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <ellipse cx=\"42\" cy=\"100\" rx=\"7\" ry=\"5\" fill=\"#e58b88\" stroke=\"#2b211d\" stroke-width=\"1.5\"/>    <circle cx=\"36\" cy=\"91\" r=\"2.2\" fill=\"#2b211d\"/><circle cx=\"48\" cy=\"91\" r=\"2.2\" fill=\"#2b211d\"/>    <text x=\"42\" y=\"70\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#2b211d\">？？？</text>    <rect x=\"78\" y=\"78\" width=\"68\" height=\"34\" fill=\"#9a7b56\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <line x1=\"94\" y1=\"78\" x2=\"94\" y2=\"112\" stroke=\"#2b211d\" stroke-width=\"1.5\"/>    <line x1=\"118\" y1=\"78\" x2=\"118\" y2=\"112\" stroke=\"#2b211d\" stroke-width=\"1.5\"/>    <text x=\"112\" y=\"132\" text-anchor=\"middle\" font-size=\"12\" fill=\"#a63a2b\">✕ 过不去</text>  </g>  <g transform=\"translate(206,52)\">    <rect x=\"14\" y=\"0\" width=\"80\" height=\"30\" rx=\"4\" fill=\"#0140c4\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"54\" y=\"20\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"bold\" fill=\"#fff\">按住 K</text>    <path d=\"M 10 52 H 98\" stroke=\"#0140c4\" stroke-width=\"3\" stroke-dasharray=\"5 4\" marker-end=\"url(#mc-arr-b)\"/>    <text x=\"54\" y=\"76\" text-anchor=\"middle\" font-size=\"13\" fill=\"#0140c4\">反方向转</text>    <text x=\"54\" y=\"94\" text-anchor=\"middle\" font-size=\"11\" fill=\"#6e6558\">猪留在原地</text>  </g>  <g transform=\"translate(328,20)\">    <rect x=\"0\" y=\"0\" width=\"168\" height=\"148\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"12\" y=\"22\" font-size=\"13\" fill=\"#0140c4\">② 货架倒带立回原位</text>    <circle cx=\"42\" cy=\"96\" r=\"18\" fill=\"#f7c8c0\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <ellipse cx=\"42\" cy=\"100\" rx=\"7\" ry=\"5\" fill=\"#e58b88\" stroke=\"#2b211d\" stroke-width=\"1.5\"/>    <path d=\"M 66 96 H 134\" stroke=\"#2b211d\" stroke-width=\"2.5\" marker-end=\"url(#mc-arr)\"/>    <rect x=\"78\" y=\"34\" width=\"28\" height=\"44\" fill=\"#9a7b56\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <path d=\"M 126 70 C 122 50, 112 44, 108 44\" fill=\"none\" stroke=\"#0140c4\" stroke-width=\"2\" stroke-dasharray=\"3 3\" marker-end=\"url(#mc-arr-b)\"/>    <rect x=\"138\" y=\"78\" width=\"18\" height=\"36\" fill=\"#ffd98c\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"112\" y=\"132\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1f7a3f\">✓ 通行出门</text>  </g></svg>",["tips"]={{"按住 K / Shift","小猪逆时针旋转，场景里的物件沿原路倒退"},{"猪不倒带","倒带时你依然可以自由走动，松开 K 即可停在任意时刻"}}},["store:1"]={["no"]="手记 02",["title"]="冲撞滑行 · 倒带急刹",["sub"]="地面湿滑一撞到底，靠倒带让箱子退回圆板上",["svg"]="<svg viewBox=\"0 0 520 190\" class=\"mc-svg\" aria-hidden=\"true\">  <defs>    <marker id=\"mc-a2\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 1 1 L 9 5 L 1 9 z\" fill=\"#2b211d\"/></marker>    <marker id=\"mc-b2\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 1 1 L 9 5 L 1 9 z\" fill=\"#0140c4\"/></marker>  </defs>  <g transform=\"translate(24,16)\">    <rect x=\"0\" y=\"0\" width=\"472\" height=\"72\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"14\" y=\"20\" font-size=\"13\" fill=\"#7a6e5d\">① 按 J / 空格 冲撞：箱子直接滑到墙边，越过圆板</text>    <circle cx=\"48\" cy=\"46\" r=\"14\" fill=\"#f7c8c0\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <rect x=\"78\" y=\"31\" width=\"30\" height=\"30\" fill=\"#c69c6d\" stroke=\"#2b211d\" stroke-width=\"2\" stroke-dasharray=\"3 3\" opacity=\"0.5\"/>    <circle cx=\"250\" cy=\"46\" r=\"15\" fill=\"none\" stroke=\"#8a7f6d\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/>    <text x=\"250\" y=\"50\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7a6e5d\">圆板</text>    <path d=\"M 114 46 H 392\" stroke=\"#2b211d\" stroke-width=\"2.5\" marker-end=\"url(#mc-a2)\"/>    <rect x=\"402\" y=\"31\" width=\"30\" height=\"30\" fill=\"#c69c6d\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <line x1=\"440\" y1=\"16\" x2=\"440\" y2=\"66\" stroke=\"#2b211d\" stroke-width=\"4\"/>  </g>  <g transform=\"translate(24,102)\">    <rect x=\"0\" y=\"0\" width=\"472\" height=\"72\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"14\" y=\"20\" font-size=\"13\" fill=\"#0140c4\">② 按住 K 倒带：等箱子退回圆板正中，立刻松手！</text>    <circle cx=\"250\" cy=\"46\" r=\"17\" fill=\"#ffd98c\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <rect x=\"235\" y=\"31\" width=\"30\" height=\"30\" fill=\"#c69c6d\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <rect x=\"402\" y=\"31\" width=\"30\" height=\"30\" fill=\"#c69c6d\" stroke=\"#2b211d\" stroke-width=\"1.5\" stroke-dasharray=\"3 3\" opacity=\"0.45\"/>    <path d=\"M 396 46 H 274\" stroke=\"#0140c4\" stroke-width=\"2.5\" stroke-dasharray=\"5 4\" marker-end=\"url(#mc-b2)\"/>    <text x=\"86\" y=\"51\" font-size=\"13\" font-weight=\"bold\" fill=\"#1f7a3f\">✓ 松开 K 压亮圆板开门</text>  </g></svg>",["tips"]={{"J / 空格 冲撞","走路推不动纸箱，必须冲撞；纸箱一滑就会滑到底"},{"倒带半路截停","滑过头没关系，按住 K 让它退回圆板上再松手"}}},["store:3"]={["no"]="手记 03",["title"]="撞倒高货架 · 进门再倒带",["sub"]="高货架能朝冲撞方向倒下压板；猪先进门再倒带关门",["svg"]="<svg viewBox=\"0 0 520 190\" class=\"mc-svg\" aria-hidden=\"true\">  <defs><marker id=\"mc-a3\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 1 1 L 9 5 L 1 9 z\" fill=\"#2b211d\"/></marker></defs>  <g transform=\"translate(24,20)\">    <rect x=\"0\" y=\"0\" width=\"218\" height=\"148\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"12\" y=\"22\" font-size=\"13\" fill=\"#7a6e5d\">① 从哪边撞，高货架往哪边倒</text>    <circle cx=\"176\" cy=\"92\" r=\"15\" fill=\"#f7c8c0\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <path d=\"M 156 92 H 130\" stroke=\"#2b211d\" stroke-width=\"2.5\" marker-end=\"url(#mc-a3)\"/>    <rect x=\"98\" y=\"48\" width=\"26\" height=\"58\" fill=\"#9a7b56\" stroke=\"#2b211d\" stroke-width=\"2\" stroke-dasharray=\"3 3\" opacity=\"0.5\"/>    <circle cx=\"52\" cy=\"96\" r=\"14\" fill=\"#ffd98c\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <rect x=\"36\" y=\"80\" width=\"62\" height=\"26\" fill=\"#9a7b56\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"108\" y=\"132\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1f7a3f\">✓ 倒下也能压亮圆板 / 当挡板</text>  </g>  <g transform=\"translate(278,20)\">    <rect x=\"0\" y=\"0\" width=\"218\" height=\"148\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"12\" y=\"22\" font-size=\"13\" fill=\"#0140c4\">② 门口的板会把门堵死？</text>    <line x1=\"20\" y1=\"76\" x2=\"82\" y2=\"76\" stroke=\"#2b211d\" stroke-width=\"4\"/>    <line x1=\"136\" y1=\"76\" x2=\"198\" y2=\"76\" stroke=\"#2b211d\" stroke-width=\"4\"/>    <circle cx=\"109\" cy=\"44\" r=\"15\" fill=\"#f7c8c0\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"109\" y=\"24\" text-anchor=\"middle\" font-size=\"11\" fill=\"#0140c4\">猪先进门里</text>    <circle cx=\"109\" cy=\"96\" r=\"14\" fill=\"#ffd98c\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <rect x=\"94\" y=\"81\" width=\"30\" height=\"30\" fill=\"#c69c6d\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"109\" y=\"132\" text-anchor=\"middle\" font-size=\"12\" fill=\"#2b211d\">先进门 → 再按 K 让箱子退回门口</text>  </g></svg>",["tips"]={{"高货架可撞倒","朝哪个方向冲撞，高货架就往哪边倒下，能压普通圆板也能当挡板"},{"先上车后补票","如果压板的箱子会堵住门，先把箱子撞开、猪先进门，再按 K 倒带让箱子退回来"}}},["store:4"]={["no"]="手记 04",["title"]="金色箱子 · 覆水难收",["sub"]="金色的东西属于「现在」，不受倒带影响",["svg"]="<svg viewBox=\"0 0 520 190\" class=\"mc-svg\" aria-hidden=\"true\">  <g transform=\"translate(24,20)\">    <rect x=\"0\" y=\"0\" width=\"218\" height=\"148\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"12\" y=\"24\" font-size=\"13\" fill=\"#7a6e5d\">普通纸箱 vs 金色箱子</text>    <rect x=\"28\" y=\"48\" width=\"36\" height=\"36\" fill=\"#c69c6d\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"80\" y=\"64\" font-size=\"13\" fill=\"#2b211d\">普通纸箱：按 K 会倒退</text>    <text x=\"80\" y=\"80\" font-size=\"11\" fill=\"#7a6e5d\">可随时倒带借位当挡板</text>    <rect x=\"28\" y=\"96\" width=\"36\" height=\"36\" fill=\"#f6c85f\" stroke=\"#8a5a12\" stroke-width=\"2.5\"/>    <text x=\"80\" y=\"112\" font-size=\"13\" font-weight=\"bold\" fill=\"#8a5a12\">金色箱子：按 K 纹丝不动</text>    <text x=\"80\" y=\"128\" font-size=\"11\" fill=\"#8a5a12\">金色圆板只认金色箱子</text>  </g>  <g transform=\"translate(278,20)\">    <rect x=\"0\" y=\"0\" width=\"218\" height=\"148\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"12\" y=\"24\" font-size=\"13\" fill=\"#0140c4\">解法：先垫背，再撞金箱</text>    <rect x=\"94\" y=\"96\" width=\"30\" height=\"30\" fill=\"#c69c6d\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"164\" y=\"114\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7a6e5d\">① 普通箱当挡板</text>    <circle cx=\"109\" cy=\"64\" r=\"15\" fill=\"#ffe699\" stroke=\"#8a5a12\" stroke-width=\"2\"/>    <rect x=\"94\" y=\"49\" width=\"30\" height=\"30\" fill=\"#f6c85f\" stroke=\"#8a5a12\" stroke-width=\"2.5\"/>    <text x=\"109\" y=\"140\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1f7a3f\">② 金箱撞上挡板，停在金板上</text>  </g></svg>",["tips"]={{"金色 = 现在","金色箱子和小猪一样不吃倒带，一旦撞进死角只能按 R 重来"},{"借用挡板","先用会倒带的普通箱子或高货架卡住位置，再把金色箱子撞过去"}}},["meeting:0"]={["no"]="手记 05",["title"]="三种时间 · 同源合体",["sub"]="下午的档案盒 + 今晚的全息投影 ＝ 现在的定稿金盒",["svg"]="<svg viewBox=\"0 0 520 190\" class=\"mc-svg\" aria-hidden=\"true\">  <defs><marker id=\"mc-a5\" viewBox=\"0 0 10 10\" refX=\"7\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M 1 1 L 9 5 L 1 9 z\" fill=\"#2b211d\"/></marker></defs>  <g transform=\"translate(20,22)\">    <rect x=\"0\" y=\"0\" width=\"136\" height=\"144\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <rect x=\"46\" y=\"28\" width=\"44\" height=\"44\" fill=\"#c69c6d\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"68\" y=\"94\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"bold\" fill=\"#2b211d\">下午的档案盒</text>    <text x=\"68\" y=\"114\" text-anchor=\"middle\" font-size=\"12\" fill=\"#7a6e5d\">会倒带 · 有重量</text>    <text x=\"68\" y=\"132\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7a6e5d\">能压普通光斑</text>  </g>  <text x=\"172\" y=\"98\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"bold\" fill=\"#2b211d\">＋</text>  <g transform=\"translate(188,22)\">    <rect x=\"0\" y=\"0\" width=\"136\" height=\"144\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <rect x=\"46\" y=\"28\" width=\"44\" height=\"44\" fill=\"#c7f9f0\" stroke=\"#1d8a7d\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/>    <text x=\"68\" y=\"94\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"bold\" fill=\"#1d8a7d\">今晚的投影</text>    <text x=\"68\" y=\"114\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1d8a7d\">不倒带 · 没重量</text>    <text x=\"68\" y=\"132\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1d8a7d\">只压全息感应板</text>  </g>  <path d=\"M 334 94 H 362\" stroke=\"#2b211d\" stroke-width=\"3\" marker-end=\"url(#mc-a5)\"/>  <g transform=\"translate(370,22)\">    <rect x=\"0\" y=\"0\" width=\"130\" height=\"144\" rx=\"4\" fill=\"#fff3d1\" stroke=\"#8a5a12\" stroke-width=\"2.5\"/>    <rect x=\"43\" y=\"28\" width=\"44\" height=\"44\" fill=\"#f6c85f\" stroke=\"#8a5a12\" stroke-width=\"2.5\"/>    <text x=\"65\" y=\"94\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"bold\" fill=\"#8a5a12\">现在的定稿</text>    <text x=\"65\" y=\"114\" text-anchor=\"middle\" font-size=\"12\" fill=\"#8a5a12\">不倒带 · 有重量</text>    <text x=\"65\" y=\"132\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8a5a12\">压亮金色光斑</text>  </g></svg>",["tips"]={{"合体落点规则","两只同源盒子相撞合体时，生成的金盒永远落在「没在动的那一只」的位置！"},{"倒带也能合体","把投影推到目标位，再按 K 让下午的盒子倒退回来撞上它，同样能在原地合体"}}},["office:0"]={["no"]="手记 06",["title"]="两份方案 · 认准便利贴",["sub"]="黄签是你的方案，蓝绿签是老陈的关联案，不同份撞上不会合体",["svg"]="<svg viewBox=\"0 0 520 190\" class=\"mc-svg\" aria-hidden=\"true\">  <g transform=\"translate(24,20)\">    <rect x=\"0\" y=\"0\" width=\"218\" height=\"148\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"12\" y=\"24\" font-size=\"13\" fill=\"#1f7a3f\">✓ 同一份方案（黄签 A + 黄签 A）</text>    <rect x=\"34\" y=\"54\" width=\"40\" height=\"40\" fill=\"#c69c6d\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <rect x=\"40\" y=\"60\" width=\"14\" height=\"10\" fill=\"#ffd966\" stroke=\"#2b211d\" stroke-width=\"1\"/>    <text x=\"92\" y=\"80\" font-size=\"20\" font-weight=\"bold\" fill=\"#2b211d\">→</text>    <rect x=\"114\" y=\"54\" width=\"40\" height=\"40\" fill=\"#c7f9f0\" stroke=\"#1d8a7d\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/>    <rect x=\"120\" y=\"60\" width=\"14\" height=\"10\" fill=\"#ffd966\" stroke=\"#1d8a7d\" stroke-width=\"1\"/>    <text x=\"109\" y=\"126\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#8a5a12\">＝ 合体成金色定稿</text>  </g>  <g transform=\"translate(278,20)\">    <rect x=\"0\" y=\"0\" width=\"218\" height=\"148\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"12\" y=\"24\" font-size=\"13\" fill=\"#a63a2b\">✕ 不同份方案（黄签 A 撞 蓝签 B）</text>    <rect x=\"34\" y=\"54\" width=\"40\" height=\"40\" fill=\"#c69c6d\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <rect x=\"40\" y=\"60\" width=\"14\" height=\"10\" fill=\"#ffd966\" stroke=\"#2b211d\" stroke-width=\"1\"/>    <text x=\"92\" y=\"80\" font-size=\"20\" font-weight=\"bold\" fill=\"#a63a2b\">✕</text>    <rect x=\"114\" y=\"54\" width=\"40\" height=\"40\" fill=\"#c7f9f0\" stroke=\"#1d8a7d\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/>    <rect x=\"120\" y=\"60\" width=\"14\" height=\"10\" fill=\"#5cd6c8\" stroke=\"#1d8a7d\" stroke-width=\"1\"/>    <text x=\"109\" y=\"126\" text-anchor=\"middle\" font-size=\"12\" fill=\"#2b211d\">不合体！只会挡路并把力传过去</text>  </g></svg>",["tips"]={{"区分 A / B","暖黄便利贴是你的本职方案，蓝绿便利贴是老陈那份关联案"},{"隔山打牛","不同份的盒子撞上不会合体，但会把冲击力传给后面的盒子"}}},["office:1"]={["no"]="手记 07",["title"]="死锁板 · 分支锁定",["sub"]="红色锁板一旦被有重量的箱子压住，门或出口就会当场锁死",["svg"]="<svg viewBox=\"0 0 520 190\" class=\"mc-svg\" aria-hidden=\"true\">  <g transform=\"translate(24,20)\">    <rect x=\"0\" y=\"0\" width=\"218\" height=\"148\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"12\" y=\"24\" font-size=\"13\" fill=\"#a63a2b\">① 重物压上红色死锁板 → 出口锁死</text>    <circle cx=\"72\" cy=\"84\" r=\"22\" fill=\"#f5b8a6\" stroke=\"#c84b31\" stroke-width=\"2.5\"/>    <rect x=\"54\" y=\"66\" width=\"36\" height=\"36\" fill=\"#c69c6d\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"152\" y=\"80\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"bold\" fill=\"#c84b31\">门 / 出口锁死</text>    <text x=\"152\" y=\"100\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7a6e5d\">可临时借它当挡板</text>  </g>  <g transform=\"translate(278,20)\">    <rect x=\"0\" y=\"0\" width=\"218\" height=\"148\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"12\" y=\"24\" font-size=\"13\" fill=\"#0140c4\">② 借完挡板后，按 K 倒带撤走解锁</text>    <circle cx=\"72\" cy=\"84\" r=\"22\" fill=\"#f5b8a6\" stroke=\"#c84b31\" stroke-width=\"2\"/>    <text x=\"72\" y=\"89\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c84b31\">空出</text>    <text x=\"152\" y=\"80\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"bold\" fill=\"#1f7a3f\">✓ 撤走即解锁</text>    <text x=\"152\" y=\"100\" text-anchor=\"middle\" font-size=\"11\" fill=\"#7a6e5d\">投影不倒带，留在感应板上</text>  </g></svg>",["tips"]={{"死锁板规则","只要红色锁板上压着有重量的箱子，哪怕感应板全亮，门或出口也打不开"},{"过河拆桥","可以先拿下午的箱子停在死锁板上替投影当挡板，等投影就位后再按 K 倒带把箱子撤走"}}},["dorm:0"]={["no"]="手记 08",["title"]="断电板 · 拔网线穿模术",["sub"]="压住紫色闪电板即断电：今晚的投影全部变成虚影，来电瞬间重叠即合体",["svg"]="<svg viewBox=\"0 0 520 190\" class=\"mc-svg\" aria-hidden=\"true\">  <g transform=\"translate(24,20)\">    <rect x=\"0\" y=\"0\" width=\"218\" height=\"148\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"12\" y=\"24\" font-size=\"13\" fill=\"#5b4bc4\">① 压住断电板：投影变虚影可穿过</text>    <circle cx=\"52\" cy=\"84\" r=\"18\" fill=\"#d9d2ff\" stroke=\"#5b4bc4\" stroke-width=\"2.5\"/>    <text x=\"52\" y=\"89\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5b4bc4\">断电</text>    <rect x=\"108\" y=\"66\" width=\"36\" height=\"36\" fill=\"none\" stroke=\"#1d8a7d\" stroke-width=\"2\" stroke-dasharray=\"3 4\" opacity=\"0.55\"/>    <line x1=\"86\" y1=\"84\" x2=\"178\" y2=\"84\" stroke=\"#2b211d\" stroke-width=\"2.5\"/>    <text x=\"126\" y=\"126\" text-anchor=\"middle\" font-size=\"12\" fill=\"#5b4bc4\">猪、箱子、倒带都能直接穿过去</text>  </g>  <g transform=\"translate(278,20)\">    <rect x=\"0\" y=\"0\" width=\"218\" height=\"148\" rx=\"4\" fill=\"#f3ebd8\" stroke=\"#2b211d\" stroke-width=\"2\"/>    <text x=\"12\" y=\"24\" font-size=\"13\" fill=\"#8a5a12\">② 挪开来电：重叠的同源盒当场合体</text>    <rect x=\"86\" y=\"56\" width=\"44\" height=\"44\" fill=\"#f6c85f\" stroke=\"#8a5a12\" stroke-width=\"2.5\"/>    <text x=\"108\" y=\"83\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#2b211d\">合体!</text>    <text x=\"109\" y=\"126\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1f7a3f\">✓ 趁断电叠进同位置，来电即定稿</text>  </g></svg>",["tips"]={{"断电虚化","紫色断电板被压住时，所有「今晚的投影 / 外卖袋」变成虚影：不挡路、不挡倒带、也压不亮全息板"},{"通电即合体","趁断电把下午盒停在同源投影的位置上，撞开断电板上的箱子恢复供电，两只盒子当场原地合体"}}}}
